mapper.select:
SELECT A.FINPROD_ID id, IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) text, b.PAY_TYPE object FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID
WHERE A.IS_CHL = #{Y}
AND A.FINPROD_TYPE2 = #{F28}

    AND A.FINPROD_ID = #{initValue}


    AND (A.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%'))
    )

SELECT A.FINPROD_ID id, IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) text, b.PAY_TYPE payType , b.COLLECT_TYPE collectType FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID WHERE A.IS_CHL = #{Y} AND A.FINPROD_TYPE2 = #{F28}
AND A.FINPROD_ID = #{initValue}
AND (A.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) )

SELECT A.FINPROD_ID id, IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) text
FROM FIN_PRODUCT A
inner join FIN_PRODUCT_ADD B
on A.FINPROD_ID = B.FINPROD_ID
WHERE A.IS_CHL = #{Y}
AND FINPROD_TYPE2 = #{F28}
AND B.PAY_TYPE = #{HKFS_YCXHK}

    AND A.FINPROD_ID = #{initValue}


    AND (A.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%'))
    )
